import React from 'react';
import { 
  Trophy, 
  Award, 
  Flame, 
  Star, 
  Zap, 
  Lock,
  CheckCircle2,
  Gift
} from 'lucide-react';
import { Badge } from '../types';

interface RewardsPanelProps {
  points: number;
  streak: number;
  unlockedBadges: string[];
}

const RewardsPanel: React.FC<RewardsPanelProps> = ({ 
  points, 
  streak, 
  unlockedBadges 
}) => {
  const badges = [
    { id: 'week-warrior', name: 'Week Warrior', desc: 'Maintain a 7-day 100% streak.', icon: Flame, color: 'text-orange-500', bg: 'bg-orange-500/10' },
    { id: 'month-master', name: 'Month Master', desc: 'Maintain a 30-day 100% streak.', icon: Award, color: 'text-purple-500', bg: 'bg-purple-500/10' },
    { id: 'consistency-king', name: 'Consistency King', desc: 'Complete 60 days in total.', icon: Zap, color: 'text-yellow-500', bg: 'bg-yellow-500/10' },
    { id: 'champion', name: 'Elite Champion', desc: 'Finish the full 180-day challenge.', icon: Trophy, color: 'text-blue-500', bg: 'bg-blue-500/10' },
  ];

  const milestones = [
    { p: 1000, label: 'Early Adopter' },
    { p: 5000, label: 'Momentum Builder' },
    { p: 15000, label: 'Habit Architect' },
    { p: 50000, label: 'Top 1% Achieve' }
  ];

  const currentLevel = milestones.filter(m => points >= m.p).length;
  const nextMilestone = milestones[currentLevel] || { p: 100000, label: 'Ultimate Legend' };
  const progressToNext = Math.min((points / nextMilestone.p) * 100, 100);

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-12 animate-fade-in">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div className="space-y-1">
          <h2 className="text-sm font-bold tracking-widest text-yellow-500 uppercase">Achievements & Rewards</h2>
          <h1 className="text-4xl font-bold tracking-tight">The Trophy Room</h1>
          <p className="text-slate-400 font-medium">Your discipline converted into digital honor.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left: Points & Rank */}
        <div className="lg:col-span-1 space-y-8">
          <div className="glass-card p-10 bg-gradient-to-br from-blue-600/20 to-purple-600/20 text-center border-blue-500/10">
             <div className="inline-flex p-4 rounded-3xl bg-blue-600/20 text-blue-400 mb-6 shadow-xl shadow-blue-500/10 rotate-3">
               <Trophy size={40} className="animate-float" />
             </div>
             <h3 className="text-xs font-bold text-blue-400 uppercase tracking-widest mb-2">Total Accumulated Points</h3>
             <p className="text-6xl font-black text-white tracking-tighter mb-4">{points.toLocaleString()}</p>
             <div className="px-4 py-1.5 bg-white/5 inline-flex rounded-full text-xs font-bold text-slate-300 uppercase tracking-widest border border-white/5">
                Level {currentLevel + 1}: {milestones[currentLevel]?.label || 'Beginner'}
             </div>

             <div className="mt-10 space-y-3">
                <div className="flex justify-between text-[10px] font-bold text-slate-500 uppercase tracking-widest">
                  <span>Next Rank: {nextMilestone.label}</span>
                  <span>{progressToNext.toFixed(1)}%</span>
                </div>
                <div className="w-full h-2 bg-white/5 rounded-full overflow-hidden">
                   <div 
                     className="h-full bg-gradient-to-r from-blue-500 to-purple-500 rounded-full transition-all duration-1000"
                     style={{ width: `${progressToNext}%` }}
                   />
                </div>
                <p className="text-[10px] text-slate-500 italic mt-2">Earn {(nextMilestone.p - points).toLocaleString()} more points to level up.</p>
             </div>
          </div>

          <div className="glass-card p-6 border-orange-500/10 bg-orange-500/5">
             <div className="flex items-center gap-4 mb-6">
               <div className="w-12 h-12 rounded-2xl bg-orange-500/20 flex items-center justify-center text-orange-500">
                 <Zap size={24} className="fill-orange-500/30" />
               </div>
               <div>
                  <h4 className="font-bold text-white uppercase text-xs tracking-widest">Current Multiplier</h4>
                  <p className="text-2xl font-black text-orange-400">x1.{Math.min(streak, 10)} Bonus</p>
               </div>
             </div>
             <p className="text-xs text-slate-400 leading-relaxed">
               Every day you maintain a streak, your point value for tasks increases slightly. 
               Don't let the flame die out!
             </p>
          </div>
        </div>

        {/* Right: Badges Grid */}
        <div className="lg:col-span-2 space-y-8">
           <h3 className="text-xl font-bold flex items-center gap-3">
              <Star size={24} className="text-yellow-500 fill-yellow-500" />
              Legendary Badges
           </h3>

           <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {badges.map((badge) => {
                const isUnlocked = unlockedBadges.includes(badge.id);
                const Icon = badge.icon;
                return (
                  <div 
                    key={badge.id}
                    className={`glass-card p-6 flex gap-5 group transition-all duration-500 relative ${
                      isUnlocked 
                        ? `bg-gradient-to-br ${badge.bg} border-white/10 scale-100 shadow-xl` 
                        : 'bg-white/2 opacity-40 grayscale translate-y-1'
                    }`}
                  >
                    {!isUnlocked && (
                       <div className="absolute top-4 right-4 text-slate-600">
                         <Lock size={16} />
                       </div>
                    )}
                    <div className={`w-16 h-16 rounded-2xl ${badge.bg} flex items-center justify-center flex-shrink-0 transition-transform group-hover:scale-110 duration-500`}>
                      <Icon className={`${badge.color} ${isUnlocked ? 'animate-pulse' : ''}`} size={32} />
                    </div>
                    <div className="space-y-1 py-1">
                      <div className="flex items-center gap-2">
                        <h4 className="font-black text-white uppercase text-sm tracking-widest">{badge.name}</h4>
                        {isUnlocked && <CheckCircle2 size={14} className="text-emerald-500" />}
                      </div>
                      <p className="text-xs text-slate-400 leading-relaxed font-medium">
                        {badge.desc}
                      </p>
                      {isUnlocked ? (
                         <span className="inline-block mt-3 text-[10px] font-bold text-emerald-400 uppercase tracking-widest bg-emerald-500/10 px-2 py-0.5 rounded-md">UNLOCKED</span>
                      ) : (
                         <span className="inline-block mt-3 text-[10px] font-bold text-slate-500 uppercase tracking-widest">LOCKED</span>
                      )}
                    </div>
                  </div>
                );
              })}
           </div>

           <div className="glass-card p-10 bg-gradient-to-r from-emerald-600/10 to-transparent border-emerald-500/10 text-center relative overflow-hidden">
              <div className="absolute -left-10 -bottom-10 w-40 h-40 bg-emerald-500/10 blur-3xl" />
              <Gift className="mx-auto text-emerald-400 mb-4" size={32} />
              <h3 className="text-xl font-bold mb-2">Unlocked a Milestone?</h3>
              <p className="text-sm text-slate-400 max-w-md mx-auto mb-6">
                Consistent performance unlocks exclusive digital rewards and the respect of the community. Reach Day 90 to unlock the "Midway Titan" secret badge.
              </p>
              <button className="px-8 py-3 bg-emerald-600/20 text-emerald-400 border border-emerald-500/20 rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-emerald-600/30 transition-all">
                View Reward History
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

export default RewardsPanel;
